mapper.update:
UPDATE MEMBER 
SET PW=#{newPw} 
WHERE ID=#{id}

UPDATE MEMBER
SET POINT = NVL(POINT, 0) + (
    SELECT POINT
    FROM ACHIEVEMENT
    WHERE ACHIEVE_NUM = #{achieveNum}
)
WHERE M_NUM = #{mNum}

UPDATE MEMBER
SET GOODS = #{goods}
WHERE M_NUM = #{mNum}
